 * High-performance portfolio calculations using C extension
 *
 * Contiguous float64 NumPy arrays are accessed with zero copies through the
 * NumPy C API.  Nested Python sequences (list/tuple of rows) are consumed
 * directly, which avoids materialising a large temporary array.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

/* Convert an element to double, allowing ints and NumPy scalars. */
static int element_as_double(PyObject *item, double *out) {
    if (PyFloat_CheckExact(item)) {
        *out = PyFloat_AS_DOUBLE(item);
        return 0;
    }
    double v = PyFloat_AsDouble(item);
    if (v == -1.0 && PyErr_Occurred())
        return -1;
    *out = v;
    return 0;
}

/*
 * Compute x^T * S * x directly from a sequence of rows.
 *
 * Returns 1 on success, 0 if `rows` is not a list/tuple, -1 on error.
 */
static int risk_squared_from_rows(PyObject *rows, const double *w, npy_intp n,
                                  double *result) {
    const int rows_is_list = PyList_Check(rows);
    if (!rows_is_list && !PyTuple_Check(rows))
        return 0;

    const npy_intp nrows = rows_is_list ? PyList_GET_SIZE(rows)
                                        : PyTuple_GET_SIZE(rows);
    if (nrows != n) {
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix dimensions must match the number of weights");
        return -1;
    }

    double total = 0.0;
    for (npy_intp i = 0; i < n; ++i) {
        PyObject *row = rows_is_list ? PyList_GET_ITEM(rows, i)
                                     : PyTuple_GET_ITEM(rows, i);
        double row_sum = 0.0;

        if (PyList_Check(row) || PyTuple_Check(row)) {
            const int row_is_list = PyList_Check(row);
            const npy_intp row_len = row_is_list ? PyList_GET_SIZE(row)
                                                 : PyTuple_GET_SIZE(row);
            if (row_len != n) {
                PyErr_SetString(
                    PyExc_ValueError,
                    "cov_matrix dimensions must match the number of weights");
                return -1;
            }
            for (npy_intp j = 0; j < n; ++j) {
                PyObject *item = row_is_list ? PyList_GET_ITEM(row, j)
                                             : PyTuple_GET_ITEM(row, j);
                double v;
                if (element_as_double(item, &v) < 0)
                    return -1;
                row_sum += v * w[j];
            }
        } else {
            /* Row is some other sequence (e.g. an ndarray): use NumPy. */
            PyArrayObject *row_array = (PyArrayObject *)PyArray_FROM_OTF(
                row, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
            if (row_array == NULL)
                return -1;
            if (PyArray_NDIM(row_array) != 1 ||
                PyArray_DIM(row_array, 0) != n) {
                Py_DECREF(row_array);
                PyErr_SetString(
                    PyExc_ValueError,
                    "cov_matrix dimensions must match the number of weights");
                return -1;
            }
            const double *restrict rd =
                (const double *)PyArray_DATA(row_array);
            for (npy_intp j = 0; j < n; ++j)
                row_sum += rd[j] * w[j];
            Py_DECREF(row_array);
        }

        total += w[i] * row_sum;
    }

    *result = total;
    return 1;
}

